ALTER TABLE public.community_salons ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'public' CHECK (visibility IN ('public','private')); ALTER TABLE public.community_salons ADD COLUMN IF NOT EXISTS description text NOT NULL DEFAULT ''; CREATE TABLE IF NOT EXISTS public.community_salon_members (salon_id uuid NOT NULL REFERENCES public.community_salons(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'member' CHECK (role IN ('owner','moderator','member')), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (salon_id,user_id)); CREATE INDEX IF NOT EXISTS community_salon_members_user_idx ON public.community_salon_members(user_id,salon_id); CREATE TABLE IF NOT EXISTS public.community_salon_join_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.community_salons(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','rejected','cancelled')), requested_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, UNIQUE (salon_id,user_id)); CREATE INDEX IF NOT EXISTS community_salon_join_requests_pending_idx ON public.community_salon_join_requests(salon_id,status,requested_at); ALTER TABLE public.community_salon_members ENABLE ROW LEVEL SECURITY; ALTER TABLE public.community_salon_join_requests ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.community_salon_members FROM anon,authenticated; REVOKE ALL ON public.community_salon_join_requests FROM anon,authenticated; GRANT SELECT ON public.community_salon_members TO authenticated; GRANT SELECT ON public.community_salon_join_requests TO authenticated;